import hashlib, json
from pathlib import Path
root = Path('/workspace')
if '${_RELEASE_APPROVED}' != 'true' or '$COMMIT_SHA' != 'a767f224cba32b60f47b0cd00ae86300c06e354a' or '$PROJECT_ID' != 'repaido':
    raise SystemExit('Exact approved release/project required before any build work.')
if '${_REGION}' != 'us-central1' or '${_SERVICE}' != 'repaido-api' or '${_IMAGE}' != 'us-central1-docker.pkg.dev/repaido/cloud-run-source-deploy/repaido-api':
    raise SystemExit('Reviewed service, image and region are required.')
raw = (root / 'release_support/reviewed-source.json').read_bytes()
if hashlib.sha256(raw).hexdigest() != 'ce969dbc9d9c9c70e89180490945c0e2fa35f20fb700687c9b295dcceec70dea':
    raise SystemExit('Reviewed source manifest hash mismatch.')
manifest = json.loads(raw)
if manifest['commit'] != 'a767f224cba32b60f47b0cd00ae86300c06e354a' or manifest['deployed_baseline'] != 'f1ef43876da329647283fcbb704aaca6944e0693':
    raise SystemExit('Reviewed source identity mismatch.')
for p in root.rglob('*'):
    if p.is_symlink():
        raise SystemExit('Linked files are forbidden in reviewed build source.')
actual = {p.relative_to(root).as_posix() for p in root.rglob('*') if p.is_file()}
if actual != set(manifest['files']) | {'release_support/reviewed-source.json'}:
    raise SystemExit('Uploaded source inventory differs from reviewed snapshot.')
for name, expected in manifest['files'].items():
    if hashlib.sha256((root / name).read_bytes()).hexdigest() != expected:
        raise SystemExit('Reviewed source digest mismatch: ' + name)
print('Exact reviewed source verified:', 'a767f224cba32b60f47b0cd00ae86300c06e354a', 'baseline', 'f1ef43876da329647283fcbb704aaca6944e0693')
